*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");

//#include("../js/controlResize.js"); // 화면 리사이징
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
scwin.vScrenID = "ULDFIS00600_P4.xml";
scwin.vAxisType = "";
scwin.vHorizLimitCnt = 0;
window.onunload = function() {
    opener.fn_getBeforeRadioBtn("ALL");
};
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};


/**
 *  화면 초기화
 */
scwin.fn_Init = function() {
    $c.cm.PanelToGroupBox(panel_Top);
    scwin.vAxisType = opener.scwin.vAxisType;
    scwin.vHorizLimitCnt = opener.scwin.vHorizLimitCnt;
    scwin.fn_InitDs();

    // 조회
    scwin.fn_Search();

    // 이전에 선택된 항목을 화면에 display
    scwin.fn_DisplayBefItem();
};


/**
 *  이미 선택되어있는 항목을 화면이 open할때 화면에 display한다.
 */
scwin.fn_DisplayBefItem = function() {
    var tmpDs = opener.dts_Fz531;
    for (var nRow = 1; nRow <= tmpDs.getTotalRow(); nRow++) {
        // AXIS_TYP 2 가로, 3 세로 / ITEM_TYP  0 년도, 1 계정, 3 회사
        if ((tmpDs.getCellData(nRow, "AXIS_TYP") == "2" || tmpDs.getCellData(nRow, "AXIS_TYP") == "3") && tmpDs.getCellData(nRow, "ITEM_TYP") == "0") {
            dts_SelectYear.insertRow();
            var nIdx = dts_SelectYear.getRowPosition();
            dts_SelectYear.setCellData(nIdx, "LV", "2");
            dts_SelectYear.setCellData(nIdx, "YYYY", tmpDs.getCellData(nRow, "ITEM_CD"));
        }
    } // end for

};




/**
 *  데이터셋 초기화.
 */
scwin.fn_InitDs = function() {

    //dts_SelectYear.setDataHeader();
    //dts_SelectAcnt.AddRow();
    //var nRow = dts_SelectAcnt.RowPosition;
    //dts_SelectAcnt.NameString(nRow, "LV") = "1";
    //dts_SelectAcnt.NameString(nRow, "ACCNT_NM") = "선택된 계정";	 // W-Craft 주석처리 및 필요시 asis 파라미터 확인 

};






/**
 *  데이터셋 clear.
 */
scwin.fn_ClearDs = function() {
    dts_Year.removeAll();
};


/**
 *  조회조건 유효성 체크
 */
scwin.fn_ChkValid = function() {
    return true;
};


/**
 * 조회
 */
scwin.fn_Search = function() {
    //데이터셋 초기화
    scwin.fn_ClearDs();

    // 조회조건 필수 체크.
    if (!scwin.fn_ChkValid()) {
        return;
    }

    // Lodaing~~~ 표시
    $c.cm.ShowWin(panel_Top);
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamic" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.fis.select.year" + "&outputMessageId=FIS_YEAR_LIST" + "&param01=Y";
    dts_Year.DataID = encodeURI(url);
    dts_Year.Reset();
};


/**
 * 선택된 값을 오프너에 전달한다.
 */
scwin.fn_SetParam = async function() {
    if (dts_SelectYear.getTotalRow() < 1) {
        return;
    }
    var arrPar = new Array();
    for (var nRow = 1; nRow <= dts_SelectYear.getTotalRow(); nRow++) {
        var sItemCd = dts_SelectYear.getCellData(nRow, "YYYY");
        var sItemNM = dts_SelectYear.getCellData(nRow, "YYYY");
        var sItemTyp = "0"; // 0:년도, 1:계정, 3:회사
        var sAxisTyp = scwin.vAxisType; // AXIS_TYP  1:기준, 2: 가로, 3:세로
        var sColYear = "0000"; // COL_YEAR

        if (sItemCd != "") {
            arrPar[nRow - 1] = {
                ITEM_CD: sItemCd,
                ITEM_NM: sItemNM,
                ITEM_TYP: sItemTyp,
                AXIS_TYP: sAxisTyp,
                COL_YEAR: sColYear
            };
        }
    }
    $c.frame.path("../").fn_SetAxisInfo(arrPar);
    await $c.frame.CloseFrame();
};


/**
 * 선택제거
 */
scwin.fn_RmSelected = function() {
    trv_SelectedYear.ReDraw = false;
    for (var nRow = dts_SelectYear.getTotalRow(); nRow >= 1; nRow--) {
        if (trv_SelectedYear.findNodeByIndex(nRow, false).checked) {
            $c.cp.removeRow(dts_SelectYear, nRow);
        }
    }
    trv_SelectedYear.ReDraw = true;
};


/**
 * 선택
 */
scwin.fn_Selected = function() {
    //dts_SelectYear.ClearData();

    // 가로 세팅이면 갯수 체크 :  2 가로, 3 세로
    if (scwin.vAxisType == "2") {
        // 선택된것 갯수 
        var nSelectCnt = dts_SelectYear.getTotalRow();
        for (var nRow = 1; nRow <= dts_Year.getTotalRow(); nRow++) {
            if (trv_Year.findNodeByIndex(nRow, false).checked) {
                nSelectCnt++;
            }
        }
        // 갯수체크
        if (nSelectCnt > scwin.vHorizLimitCnt) {
            $c.win.alert("선택된 가로항목이 10개를 초과합니다.");
            return;
        }
    }
    for (var nRow = 1; nRow <= dts_Year.getTotalRow(); nRow++) {
        if (trv_Year.findNodeByIndex(nRow, false).checked) {
            // 중복 체크.
            var nTmpIdx1 = $c.cp.getNameValueRow(dts_SelectYear, "YYYY", dts_Year.getCellData(nRow, "YYYY"));
            if (nTmpIdx1 >= 1) {
                trv_Year.checkByIndex(nRow, false); // 체크박스 언체크
                continue;
            }
            dts_SelectYear.insertRow();
            dts_SelectYear.setCellData(dts_SelectYear.getRowPosition(), "LV", dts_Year.getCellData(nRow, "LV"));
            dts_SelectYear.setCellData(dts_SelectYear.getRowPosition(), "YYYY", dts_Year.getCellData(nRow, "YYYY"));
            trv_Year.checkByIndex(nRow, false); // 체크박스 언체크

        }
    }
};




/**
 * 전체선택
 */
scwin.fn_SelectAll = function() {
    for (var nRow = 1; nRow <= dts_Year.getTotalRow(); nRow++) {
        trv_Year.checkByIndex(nRow, true);
    }
};
scwin.dts_Year_OnLoadError = function() {
    $c.stf.alert_error(dts_Year);
};
scwin.dts_Year_OnLoadCompleted = function(rowcount) {
    if (dts_Year.errorMsg) {
        $c.win.alert(dts_Year.errorMsg);
    }
    $c.cm.CloseWin(rowcount, panel_Top);
};
scwin.gform_onload = function() {
    scwin.fn_Init();
};
scwin.img_Close_onclick = async function() {
    // 닫기버튼 클릭
    // opener.fn_getBeforeRadioBtn("ALL");
    await $c.frame.CloseFrame();
};
scwin.img_Confirm_onclick = function() {
    // 확인버튼 클릭
    scwin.fn_SetParam();
};
scwin.image_1_onclick = function() {
    scwin.fn_Selected();
};
scwin.image_2_onclick = function() {
    scwin.fn_RmSelected();
};
scwin.image_3_onclick = function() {
    scwin.fn_SelectAll();
};
